 SaveOfficeView("office-general");Call("NodePurposeClick",new Point(84+4*98+45,560));Check(office.Purpose==NodePurpose.Defense,"castle plan changes target office immediately");SaveOfficeView("office-castle");
 Call("ResetInspector");Set("_domesticSlide",0f);batch.Begin();Call("DrawPrimaryActionButtonsCore");batch.End();
 using(var image=new Texture2D(GraphicsDevice,1920,1080)){var pixels=new Color[1920*1080];GraphicsDevice.GetBackBufferData(pixels);image.SetData(pixels);using var file=File.Create(Path.Combine(Environment.GetEnvironmentVariable("GUIDE_OUTPUT")!,"guide-recall-button.png"));image.SaveAsPng(file,1920,1080);}
 }
